/** Seed the previous SQLite VFS layout using files generated by Python SQLite. */
function namespace(name) {
  let hash = 0xcbf29ce484222325n

  for (const byte of new TextEncoder().encode(name))
    hash = BigInt.asUintN(64, (hash ^ BigInt(byte)) * 0x100000001b3n)
  const suffix = hash.toString(16).padStart(16, '0').slice(0, 8)
  const sanitized = [...name.toLowerCase()]
    .map((char) => (/[a-z0-9._-]/.test(char) ? char : '_'))
    .slice(0, 64)
    .join('')

  return {
    path: `.kizunasync/${sanitized}-${suffix}/.opaque`,
    idb: `relaxed-idb-${suffix}`,
  }
}

async function opfs(name, files) {
  let directory = await navigator.storage.getDirectory()

  for (const component of namespace(name).path.split('/'))
    directory = await directory.getDirectoryHandle(component, { create: true })

  for (const [index, file] of files.entries()) {
    const entry = await directory.getFileHandle(`legacy-${index}`, {
      create: true,
    })
    const handle = await entry.createSyncAccessHandle()
    const bytes = new Uint8Array(4096 + file.bytes.length)

    bytes.set(new TextEncoder().encode(`/${name}${file.suffix}\0`))
    new DataView(bytes.buffer).setUint32(
      512,
      file.suffix === '-wal' ? 0x80000 : 0x100,
    )
    bytes.set(file.bytes, 4096)
    handle.write(bytes)
    handle.flush()
    handle.close()
  }
}

async function idb(name, files) {
  const opening = indexedDB.open(namespace(name).idb, 1)

  opening.onupgradeneeded = () =>
    opening.result.createObjectStore('blocks', { keyPath: ['path', 'offset'] })
  const database = await new Promise((resolve, reject) => {
    opening.onsuccess = () => resolve(opening.result)
    opening.onerror = () => reject(opening.error)
  })
  const tx = database.transaction('blocks', 'readwrite')
  const table = tx.objectStore('blocks')

  for (const file of files) {
    for (let offset = 0; offset < file.bytes.length; offset += 4096) {
      table.put({
        path: `/${name}${file.suffix}`,
        offset,
        data: new Uint8Array(file.bytes.slice(offset, offset + 4096)),
      })
    }
  }
  await new Promise((resolve, reject) => {
    tx.oncomplete = resolve
    tx.onabort = tx.onerror = () => reject(tx.error)
  })
  database.close()
}

self.onmessage = async ({ data }) => {
  try {
    await (data.backend === 'opfs' ? opfs : idb)(data.name, data.files)
    self.postMessage({ ok: true })
  } catch (error) {
    self.postMessage({ ok: false, message: String(error) })
  }
}
